function draw() {
  ctx.clearRect(0, 0, W, H);
  // planet
  const planetGrad = ctx.createRadialGradient(
    planet.x, planet.y, planet.r * 0.2,
    planet.x, planet.y, planet.r
  );
  planetGrad.addColorStop(0, '#666');
  planetGrad.addColorStop(1, '#111');
  ctx.fillStyle = planetGrad;
  ctx.beginPath();
  ctx.arc(planet.x, planet.y, planet.r, 0, Math.PI * 2);
  ctx.fill();
  // player ship as triangle
  const px = planet.x + Math.cos(player.angle) * player.radius;
  const py = planet.y + Math.sin(player.angle) * player.radius;
  const shipAngle = player.angle + Math.PI / 2; // point outward
  const shipSize = player.size * 2;
  ctx.fillStyle = '#0f0';
  ctx.beginPath();
  ctx.moveTo(
    px + Math.cos(shipAngle) * shipSize,
    py + Math.sin(shipAngle) * shipSize
  );
  ctx.lineTo(
    px + Math.cos(shipAngle + Math.PI * 2 / 3) * shipSize * 0.6,
    py + Math.sin(shipAngle + Math.PI * 2 / 3) * shipSize * 0.6
  );
  ctx.lineTo(
    px + Math.cos(shipAngle - Math.PI * 2 / 3) * shipSize * 0.6,
    py + Math.sin(shipAngle - Math.PI * 2 / 3) * shipSize * 0.6
  );
  ctx.closePath();
  ctx.fill();
  // asteroids
  ctx.fillStyle = '#a33';
  for (const a of asteroids) {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
    ctx.fill();
  }
  // power‑up collection
  ctx.fillStyle = '#ff0';
  for (const p of powerUps) {
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    ctx.fill();
  }
  // UI
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + Math.floor(score), 10, 20);
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#f44';
    ctx.font = '48px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', W / 2, H / 2);
  }
}

input.newString:
function draw() {
  // dark space background
  ctx.fillStyle = '#02010a';
  ctx.fillRect(0, 0, W, H);
  // starfield
  ctx.fillStyle = '#fff';
  for (const s of stars) {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
  }
  // planet with gradient
  const planetGrad = ctx.createRadialGradient(
    planet.x, planet.y, planet.r * 0.2,
    planet.x, planet.y, planet.r
  );
  planetGrad.addColorStop(0, '#666');
  planetGrad.addColorStop(1, '#111');
  ctx.fillStyle = planetGrad;
  ctx.beginPath();
  ctx.arc(planet.x, planet.y, planet.r, 0, Math.PI * 2);
  ctx.fill();
  // player ship as triangle with slight shadow
  const px = planet.x + Math.cos(player.angle) * player.radius;
  const py = planet.y + Math.sin(player.angle) * player.radius;
  const shipAngle = player.angle + Math.PI / 2; // point outward
  const shipSize = player.size * 2;
  ctx.fillStyle = '#0f0';
  ctx.beginPath();
  ctx.moveTo(
    px + Math.cos(shipAngle) * shipSize,
    py + Math.sin(shipAngle) * shipSize
  );
  ctx.lineTo(
    px + Math.cos(shipAngle + Math.PI * 2 / 3) * shipSize * 0.6,
    py + Math.sin(shipAngle + Math.PI * 2 / 3) * shipSize * 0.6
  );
  ctx.lineTo(
    px + Math.cos(shipAngle - Math.PI * 2 / 3) * shipSize * 0.6,
    py + Math.sin(shipAngle - Math.PI * 2 / 3) * shipSize * 0.6
  );
  ctx.closePath();
  ctx.fill();
  // asteroids with subtle gradient
  for (const a of asteroids) {
    const grad = ctx.createRadialGradient(
      a.x, a.y, a.r * 0.3,
      a.x, a.y, a.r
    );
    grad.addColorStop(0, '#c44');
    grad.addColorStop(1, '#822');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
    ctx.fill();
  }
  // power‑ups with glow
  for (const p of powerUps) {
    const grad = ctx.createRadialGradient(
      p.x, p.y, p.r * 0.2,
      p.x, p.y, p.r * 2
    );
    grad.addColorStop(0, '#ff0');
    grad.addColorStop(1, 'rgba(255,165,0,0)');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    ctx.fill();
  }
  // UI overlay
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + Math.floor(score), 10, 20);
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#f44';
    ctx.font = '48px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', W / 2, H / 2);
  }
}

